def verify_latest_response(latest_response):
    import re
    try:
        search = latest_response.get('Search')
        if not search:
            return 0
        uri_pattern = re.compile(r'^https?://', re.IGNORECASE)
        checked = False
        for item in search:
            poster = item.get('Poster')
            if poster is None:
                continue
            checked = True
            if poster == 'N/A':
                continue
            if not uri_pattern.match(str(poster)):
                return -1
        if not checked:
            return 0
        return 1
    except:
        return 0

